dependencies.persistence.runtimeLifecycle.trySet({
    taskId: input.taskId,
    to: 'failed',
    allowedFrom: [...input.allowedFrom],
    // 来源可能已经是终态（retry 的准入门放行 done/failed/canceled/… 六档），所以这条
    // 「终态→failed」的升级必须显式允许覆写终态，否则升级会被生命周期内核静默丢掉。
    allowTerminal: true,
    extra: {
      finishedAt: now,
      errorSummary: input.code,
      errorMessage: input.detail,
      failedNodeId: input.run.nodeId,
    },
    now,
    reason: `${input.reason}:${input.code}`,
  })

dependencies.persistence.runtimeLifecycle.trySet({
        taskId: input.taskId,
        to: 'failed',
        allowedFrom: ['interrupted'],
        allowTerminal: true,
        now: dependencies.now?.() ?? Date.now(),
        extra: {
          finishedAt: dependencies.now?.() ?? Date.now(),
          errorSummary: 'retry-child-cancel-failed',
          // 退役实现把「是哪个子任务」写进了任务行的 errorMessage——那是用户唯一能看到
          // 这个 id 的地方（抛出的 ConflictError 只进 HTTP 响应，不落库），跟着留下。
          errorMessage: `failed to cancel superseded child task '${childTaskId}': ${detail}`,
          failedNodeId: target.nodeId,
        },
        reason: 'retry-child-cancel-failed',
      })

dependencies.persistence.runtimeLifecycle.trySet({
          taskId,
          to: 'failed',
          allowedFrom: ['pending', 'running'],
          extra: {
            finishedAt: occurredAt,
            errorSummary: 'child task launch failed',
            errorMessage: error instanceof Error ? error.message : String(error),
          },
          executionContext: execution,
          now: occurredAt,
          reason: 'postgresql-child-launch',
        })

this.runtimeLifecycle.trySetWithGuard(input, async (tx) => {
        const pending = await gatesIn(tx).listPreparedManualQuestionParksTx(input.taskId)
        if (pending.length > 0) throw new ManualQuestionPending()
      })

taskLifecycle.trySetWithGuard(
        {
          taskId: input.taskId,
          to: 'interrupted',
          allowedFrom: [input.from],
          extra: {
            finishedAt: input.now,
            errorSummary: input.failureCode,
            errorMessage: input.errorMessage,
          },
          now: input.now,
          reason: 'reapOrphanRuns',
        },
